using System;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using CrossTheLine.Minigames;
public static class UpdateFastingPortraitAndScroll
{
    const string Pref="Assets/Prefabs/Minigames/FastingTopDown/";
    static Sprite pixel;static TMP_FontAsset font;
    static RectTransform Rect(string name,Transform parent,Vector2 anchor,Vector2 pos,Vector2 size){var o=new GameObject(name,typeof(RectTransform));o.transform.SetParent(parent,false);var r=o.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=anchor;r.anchoredPosition=pos;r.sizeDelta=size;return r;}
    static UnityEngine.UI.Image Image(string n,Transform p,Vector2 pos,Vector2 size,Color c){var r=Rect(n,p,Vector2.zero,pos,size);var im=r.gameObject.AddComponent<UnityEngine.UI.Image>();im.sprite=pixel;im.color=c;im.raycastTarget=false;return im;}
    static TMP_Text Text(string n,Transform p,Vector2 pos,Vector2 size,string text,int fs=16){var r=Rect(n,p,Vector2.zero,pos,size);var t=r.gameObject.AddComponent<TextMeshProUGUI>();t.font=font;t.fontSize=fs;t.text=text;t.color=new Color(1,.95f,.81f);t.raycastTarget=false;return t;}
    static void Place(TMP_Text text,Transform parent,Vector2 anchor,Vector2 pos,Vector2 size,int fs){var r=text.rectTransform;r.SetParent(parent,false);r.anchorMin=r.anchorMax=r.pivot=anchor;r.anchoredPosition=pos;r.sizeDelta=size;text.fontSize=fs;}
    static Sprite SpriteAt(string path)=>AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>().First();
    public static string Run()
    {
        if(EditorApplication.isPlaying)throw new Exception("Stop Play");var g=UnityEngine.Object.FindAnyObjectByType<FastingTopDownGame>();if(!g||g.gameObject.scene.isDirty)throw new Exception("Open saved top-down scene");var hud=g.introduction.transform.parent.gameObject;if(hud.transform.Find("PortraitCard"))throw new Exception("Already installed; preserve edits");
        pixel=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Sprite/Minigames/FastingTopDown/Pixel.png");font=g.heading.font;
        g.settings.stageMoveSpeeds=new float[]{2.5f,2.75f,3f,3.25f};g.settings.manualMoveSpeed=4.5f;g.settings.bibleSpawnChance=.03f;g.settings.pageSpawnChance=.08f;g.settings.pieceSpawnChance=.1f;g.settings.waveIntervals=new float[]{2.4f,2f,1.7f,1.4f};g.settings.flamesForFever=3;g.settings.feverSeconds=5;EditorUtility.SetDirty(g.settings);
        var fire=AssetDatabase.LoadAllAssetsAtPath("Assets/Sprite/Effect/Fire.aseprite").OfType<Sprite>().OrderBy(s=>s.name).ToArray();if(fire.Length<2)throw new Exception("Fire animation missing");
        var source=PrefabUtility.LoadPrefabContents(Pref+"Pickup.prefab");source.name="FirePickup";source.GetComponent<FastingTopDownEntity>().kind=FastingTopDownEntity.Kind.Flame;var sr=source.transform.Find("Symbol").GetComponent<SpriteRenderer>();sr.sprite=fire[0];float scale=1f/Mathf.Max(fire[0].bounds.size.x,fire[0].bounds.size.y);sr.transform.localScale=Vector3.one*scale;sr.transform.localPosition=-fire[0].bounds.center*scale;sr.color=Color.white;source.transform.Find("SymbolOutline").gameObject.SetActive(false);var loop=source.AddComponent<FastingFireSpriteLoop>();loop.target=sr;loop.frames=fire;PrefabUtility.SaveAsPrefabAsset(source,Pref+"FirePickup.prefab");PrefabUtility.UnloadPrefabContents(source);
        var firePrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Pref+"FirePickup.prefab");for(int i=0;i<g.entities.Length;i++){var e=g.entities[i];if(e.kind!=FastingTopDownEntity.Kind.Flame)continue;var root=e.gameObject;int stage=e.stage;var pos=root.transform.position;string name=root.name;PrefabUtility.ReplacePrefabAssetOfPrefabInstance(root,firePrefab,InteractionMode.AutomatedAction);e=root.GetComponent<FastingTopDownEntity>();e.stage=stage;e.kind=FastingTopDownEntity.Kind.Flame;e.transform.position=pos;e.name=name;var symbol=root.transform.Find("Symbol").GetComponent<SpriteRenderer>();symbol.sprite=fire[0];symbol.color=Color.white;symbol.transform.localScale=Vector3.one*scale;symbol.transform.localPosition=-fire[0].bounds.center*scale;g.entities[i]=e;PrefabUtility.RecordPrefabInstancePropertyModifications(e);PrefabUtility.RecordPrefabInstancePropertyModifications(e.transform);PrefabUtility.RecordPrefabInstancePropertyModifications(symbol);PrefabUtility.RecordPrefabInstancePropertyModifications(symbol.transform);}
        foreach(string n in new[]{"PrayerTrack","PrayerFill","Footer","Stamina0","Stamina1","Stamina2","Stamina3","Stamina4"}){var child=hud.transform.Find(n);if(child)child.gameObject.SetActive(false);}var header=hud.transform.Find("Header").GetComponent<RectTransform>();header.sizeDelta=new Vector2(540,38);Place(g.heading,hud.transform,new Vector2(0,1),new Vector2(24,-15),new Vector2(510,24),18);Place(g.help,hud.transform,new Vector2(0,1),new Vector2(24,-54),new Vector2(900,24),16);
        var card=Image("PortraitCard",hud.transform,new Vector2(12,12),new Vector2(520,132),new Color(.055f,.065f,.085f,.94f));card.transform.SetSiblingIndex(4);
        var portrait=Image("JesusPortrait",card.transform,new Vector2(20,20),new Vector2(96,96),Color.white);portrait.sprite=SpriteAt("Assets/Sprite/Dialogue/Jesus/JesusNormal.png");portrait.preserveAspect=true;
        var ringRect=Rect("HolyFireRing",card.transform,Vector2.zero,new Vector2(8,8),new Vector2(120,120));var ring=ringRect.gameObject.AddComponent<FastingFeverRing>();ring.raycastTarget=false;
        var view=hud.AddComponent<FastingPortraitHUD>();view.game=g;view.ring=ring;view.fireFrames=fire;
        Image("PrayerTrack",card.transform,new Vector2(142,80),new Vector2(356,26),new Color(.12f,.22f,.23f));g.prayerFill=Image("PrayerFill",card.transform,new Vector2(142,80),new Vector2(356,26),new Color(.2f,.76f,.7f));g.prayerFill.type=UnityEngine.UI.Image.Type.Filled;g.prayerFill.fillMethod=UnityEngine.UI.Image.FillMethod.Horizontal;view.prayerText=Text("PrayerValue",card.transform,new Vector2(150,81),new Vector2(338,24),"기도",17);
        Image("HealthTrack",card.transform,new Vector2(142,44),new Vector2(356,24),new Color(.25f,.1f,.1f));view.healthFill=Image("HealthFill",card.transform,new Vector2(142,44),new Vector2(356,24),new Color(.86f,.3f,.24f));view.healthFill.type=UnityEngine.UI.Image.Type.Filled;view.healthFill.fillMethod=UnityEngine.UI.Image.FillMethod.Horizontal;view.healthText=Text("HealthValue",card.transform,new Vector2(150,44),new Vector2(338,24),"체력",17);
        view.stackText=Text("HolyFireStacks",card.transform,new Vector2(5,0),new Vector2(126,20),"성령불 0/3",14);view.stackText.alignment=TextAlignmentOptions.Center;
        view.feverFlame=Image("FeverFlame",card.transform,new Vector2(12,110),new Vector2(112,112),Color.white);view.feverFlame.sprite=fire[0];view.feverFlame.preserveAspect=true;view.feverFlame.gameObject.SetActive(false);view.feverText=Text("FeverTime",card.transform,new Vector2(5,204),new Vector2(128,24),"FEVER",17);view.feverText.alignment=TextAlignmentOptions.Center;view.feverText.gameObject.SetActive(false);
        Place(g.status,card.transform,Vector2.zero,new Vector2(142,110),new Vector2(356,20),15);Place(g.items,card.transform,Vector2.zero,new Vector2(142,12),new Vector2(356,20),14);
        var controls=hud.GetComponentsInChildren<TMP_Text>(true).First(t=>t.name=="Controls");Place(controls,hud.transform,new Vector2(1,0),new Vector2(-12,12),new Vector2(280,70),15);controls.text="WASD / 방향키 : 상하좌우 이동\nE 수통 · R 재시작\n카메라 전진 · 기도 자동 충전";
        var guide=g.introduction.GetComponentsInChildren<TMP_Text>(true).First(t=>t.name=="FiveItemGuide");guide.text="카메라는 앞으로 이동합니다. WASD/방향키로 자유롭게 피하세요.\n기도는 기본 초당 1 자동 충전 / 방해 중 잠시 정지\n\n1. 수통 [E] : 정화 + 체력 1 회복 + 잠시 가속\n2. 믿음의 방패 : 다음 충돌 자동 방어 후 소모\n3. 성령불 3개 : 피버 5초 / 초상화의 불꽃과 게이지로 확인\n4. 완본 100% / 페이지 25~40% / 조각 10~25%\n5. 물 보급 : 수통 충전 + 보호 (마지막 구간 없음)\n\n피버 중 게이지가 줄어들며 0이 되면 종료됩니다.\n기도 완료 후 금색 전환선 통과 / 파란 칸 엄폐, 초록 칸 적용\n가까운 장애물은 그림이 커져도 붉은 바닥만 실제 피격 범위입니다.";
        PrefabUtility.SaveAsPrefabAssetAndConnect(hud,Pref+"FastingTopDownHUD.prefab",InteractionMode.AutomatedAction);view.game=g;PrefabUtility.RecordPrefabInstancePropertyModifications(view);EditorUtility.SetDirty(g);EditorSceneManager.MarkSceneDirty(g.gameObject.scene);EditorSceneManager.SaveScene(g.gameObject.scene);AssetDatabase.SaveAssets();return "Installed portrait HUD, fire ring and animation; four-way scrolling, stage speeds and spawn balance saved.";
